'use strict';
function saveSettings(){const topics=[...document.querySelectorAll('input[name="topic"]:checked')].map(n=>n.value);if(!topics.length){$('#settingsError').textContent='Select at least one practice module.';return;}state.config={...state.config,topics,difficulty:$('#difficulty').value,units:$('#units').value,pressure:$('#pressure').value};changed();closeDialog();render();toast('Settings saved for your next expedition.');}
function exportCSV(){const rows=[['Skill','Submitted answers','Correct answers','Accuracy percent'],...Object.entries(state.stats).map(([k,t])=>[E.skills[k].name,t.attempts,t.correct,t.attempts?(100*t.correct/t.attempts).toFixed(1):''])];download('corrupt-drive-practice.csv',rows.map(row=>row.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function importOld(){let old;try{old=JSON.parse(localStorage.getItem('corrupt-drive.v1')||'null');}catch{}if(!old||old.version!==1){toast('No original prototype save was found on this browser and site. Nothing changed.');return;}const imported=W.normalize(old);for(const f of Archive)state.archive[f.id]=(state.archive[f.id]||0)|(imported.archive[f.id]||0);for(const k in state.stats){const t=state.stats[k],u=imported.stats[k];t.attempts=Math.max(t.attempts,u.attempts);t.correct=Math.min(t.attempts,Math.max(t.correct,u.correct));}state.repairs=Math.max(state.repairs,imported.repairs);for(const f of Archive){const key=f.type==='text'?'users':f.type;state.restored[key]=Math.max(state.restored[key],W.partCount(state.archive[f.id]||0)*4);}changed();closeDialog();render();toast('Original archive and practice records merged. Your current expedition was preserved.');}
async function loadCloud(){if(saving)await saving;try{const d=await api('load');state=W.normalize(d.state);revision=d.revision;dirty=false;blocked=false;saveError='';shadow=null;changeNo++;backup();closeDialog();render();toast('Loaded the latest cloud save.');maybeTutorial();}catch(e){toast(e.message);}}
async function logout(){walking++;const ok=await flush();if(!ok||dirty){toast('Your latest changes are not saved. Export your backup, then resolve the cloud status before signing out.');closeDialog();return;}try{await api('logout');user=null;shadow=null;state=W.fresh();dirty=false;blocked=false;saveError='';clearTimeout(saveTimer);$('#dialog').close();authMode='login';authScreen();}catch(e){toast(e.message);}}
function canPlay(){if(!user)return false;if(blocked){toast('Resolve the cloud-save conflict or sign in again before changing progress.');return false;}return true;}
function doMove(dx,dy){if(!canPlay()||!active().run)return;afterAction(W.move(active(),dx,dy));}
function requestExtract(){const r=active().run;if(!r)return;if(r.question){toast('Finish the current repair first.');return;}if(r.tutorial){toast('Walk to the extraction block to finish the tutorial.');return;}const here=W.nodeAt(r),free=here?.type==='exit';if(!free&&r.charges<2){toast('Emergency extraction costs 2 scan charges. Return to the entry block for free extraction.');return;}openDialog('Extract this expedition?',`<p>${free?'The entry block provides free extraction.':'Emergency extraction consumes two scan charges.'} Your ${r.cargo.length} carried fragments will be banked.</p><p class="smalltext muted">Permanent files and practice statistics are preserved. Your temporary modules and remaining scrap end with this run.</p>${btn('Bank cargo and extract','confirm-extract','primary wide')}${btn('Keep exploring','close','ghost wide')}`);}
function contextual(){const b=$('#inspector button[data-act="continue"],#inspector button[data-act="diagnose"],#inspector button[data-act="collect"],#inspector button[data-act="finish"],#inspector button[data-act="bank"],#inspector button[data-act="trace"],#inspector button[data-act="jump"]');if(b&&!b.disabled)b.click();}
// Walking never crosses unexplored terrain automatically and stops at new encounters.
function routeTo(tx,ty){const r=active().run;if(!r||r.question||!W.floor(r,tx,ty)||!r.seen[W.idx(r,tx,ty)])return;const start=W.idx(r,r.x,r.y),goal=W.idx(r,tx,ty),queue=[start],previous=new Map([[start,null]]);while(queue.length&&!previous.has(goal)){const k=queue.shift(),x=k%r.w,y=Math.floor(k/r.w);for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const xx=x+dx,yy=y+dy,kk=W.idx(r,xx,yy);if(W.floor(r,xx,yy)&&r.seen[kk]&&!previous.has(kk)){previous.set(kk,k);queue.push(kk);}}}if(!previous.has(goal)){toast('No revealed route. Explore closer first.');return;}let path=[],k=goal;while(k!==start){path.unshift(k);k=previous.get(k);}const ticket=++walking;function step(){if(ticket!==walking||!active().run||page!=='drive'||$('#dialog').open||blocked||!path.length)return;const rr=active().run,kk=path.shift(),x=kk%rr.w,y=Math.floor(kk/rr.w);doMove(x-rr.x,y-rr.y);if(!active().run)return;const n=W.nodeAt(rr);if(n&&!['exit','station','shortcut'].includes(n.type)||rr.corrupt.includes(kk))return;setTimeout(step,110);}step();}
document.addEventListener('submit',event=>{const form=event.target;if(form.id==='authForm'){event.preventDefault();authenticate(form);return;}if(form.id==='questionForm'){event.preventDefault();if(!canPlay())return;const r=active().run;if(!r?.question)return;const answer=$('#answer').value;const result=W.submit(active(),answer);if(!result.valid){$('#answerError').textContent=result.message;return;}r.question.draft=answer;afterAction();return;}if(form.id==='secretForm'){event.preventDefault();if(!canPlay())return;const r=active().run,input=new FormData(form).get('word');if(String(input||'').trim()==='ECHO'){r.shortcutOpen=true;W.discover(active(),'relay');W.log(r,'Maintenance command accepted. The central relay is available.','good');afterAction('Relay unlocked. Look for the ↔ block in the centre corridor.');}else{const n=$('#secretError');if(n)n.textContent='The command is case-sensitive. Read the hexadecimal bytes with the ASCII table.';else toast('Not the expected command. Use the ASCII reference.');}}});
document.addEventListener('input',event=>{if(event.target.id==='asciiSearch')$('#asciiBody').innerHTML=asciiRows(event.target.value.trim());if(event.target.id==='answer'&&active().run?.question){active().run.question.draft=event.target.value;if(!shadow)changed();}});
document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,id=b.dataset.id,r=active().run;const readOnly=new Set(['close','backup','retry-save','load-cloud','confirm-load','account','logout','relogin','auth-login','auth-register','auth-recover','download-recovery','recovery-done','nav','file','filter','reference','csv','play-audio','zoom-in','zoom-out','fullscreen']);
 if(user&&!readOnly.has(a)&&!canPlay())return;
 try{switch(a){
 case 'auth-login':case 'auth-register':case 'auth-recover':if(!authBusy){authMode=a.slice(5);authScreen();}break;
 case 'close':closeDialog();break;
 case 'download-recovery':if(recoveryCode)download('corrupt-drive-recovery-code.txt',`Corrupt Drive recovery code\nUsername: ${user.username}\nCode: ${recoveryCode}\nKeep this private. It can reset your password.\n`,'text/plain');break;
 case 'recovery-done':recoveryCode=null;closeDialog();maybeTutorial();break;
 case 'nav':walking++;page=b.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});break;
 case 'missions':closeDialog();missions();break;
 case 'begin':closeDialog();if(state.run)W.finish(state,'extracted');shadow=null;W.createRun(state,id,crypto.getRandomValues(new Uint32Array(1))[0]);page='drive';zoom=1;afterAction();break;
 case 'tutorial':startTutorial();break;
 case 'exit-tutorial':shadow=null;page='drive';render();toast('Training closed. Your real expedition and progress are unchanged.');break;
 case 'move':walking++;doMove(Number(b.dataset.dx),Number(b.dataset.dy));break;
 case 'diagnose':case 'process':if(r){afterAction(W.startQuestion(active(),id));if(window.innerWidth<801)$('#inspector')?.scrollIntoView({behavior:'smooth',block:'start'});}break;
 case 'continue':if(r?.question?.feedback){W.continueQuestion(active());afterAction();}break;
 case 'collect':if(r)afterAction(W.collect(active(),id));break;
 case 'perk':if(r)afterAction(W.takePerk(active(),id,b.dataset.node));break;
 case 'recycle':{const n=r&&W.nodeAt(r);if(n?.type==='cache'&&!n.done){n.done=true;r.scrap+=12;W.log(r,'Exhausted module cache recycled: +12 scrap.','good');afterAction();}break;}
 case 'scan':if(r)afterAction(W.scan(active()));break;
 case 'patch':if(r)afterAction(W.patch(active()));break;
 case 'bank':if(r&&!r.question&&['station','exit'].includes(W.nodeAt(r)?.type)){W.bank(active());afterAction('Carried fragments banked.');}break;
 case 'finish':if(r&&!r.question&&W.nodeAt(r)?.type==='exit'){if(shadow){completeTutorial();}else{W.finish(state,'extracted');afterAction();}}break;
 case 'extract':requestExtract();break;
 case 'confirm-extract':if(r&&!r.question){const free=W.nodeAt(r)?.type==='exit';if(!free&&r.charges<2){toast('Two charges are needed.');break;}if(!free)r.charges-=2;closeDialog();W.finish(active(),'extracted');afterAction();}break;
 case 'hint':if(r?.question&&!r.question.hint){if(r.charges<1&&!r.tutorial){toast('No scan charges remain. The reference table is still free.');break;}if(!r.tutorial)r.charges--;r.question.hint=true;afterAction();}break;
 case 'cargo':cargo();break;
 case 'discard':{const index=Number(id);if(r?.cargo[index])openDialog('Discard this carried fragment?',`<p>This removes one unbanked copy from your buffer, not your permanent archive.</p>${btn('Discard fragment','confirm-discard','danger wide',`data-id="${index}"`)}${btn('Keep it','cargo','ghost wide')}`);break;}
 case 'confirm-discard':if(r&&Number.isInteger(Number(id))&&r.cargo[Number(id)]){r.cargo.splice(Number(id),1);changed();render();cargo();}break;
 case 'trace':if(r){const n=W.nodeAt(r);if(n?.type==='clue'){W.discover(active(),'trace');W.log(r,'Raw bytes logged: '+n.text+'.','info');afterAction('Trace added to your field guide.');}}break;
 case 'jump':if(r)afterAction(W.jump(active()));break;
 case 'zoom-in':zoom=Math.min(2,zoom+.25);drawMap();break;
 case 'zoom-out':zoom=Math.max(1,zoom-.25);drawMap();break;
 case 'fullscreen':{const map=$('.mapcard');if(document.fullscreenElement)await document.exitFullscreen();else if(map?.requestFullscreen)await map.requestFullscreen();else toast('Fullscreen is unavailable in this browser.');break;}
 case 'filter':filter=id;render();break;case 'file':showFile(id);break;case 'play-audio':playAudio(id);break;
 case 'reference':reference();break;case 'settings':settings();break;case 'save-settings':saveSettings();break;case 'import-old':openDialog('Merge original prototype progress?',`<p>This adds locally recovered files and keeps the higher count for each practice statistic. Your current expedition stays intact.</p>${btn('Merge original progress','confirm-import','primary wide')}${btn('Cancel','close','ghost wide')}`);break;case 'confirm-import':importOld();break;
 case 'backup':exportBackup();break;case 'retry-save':if(blocked)toast('Load the newer cloud save, or sign in again if the session expired.');else{saveError='';await flush();status();}break;
 case 'load-cloud':openDialog('Load the latest cloud save?',`<p>This replaces unsynced progress in this tab. Export a local backup first to keep a copy of those changes.</p>${btn('Export local backup','backup','ghost wide')}${btn('Load cloud save','confirm-load','primary wide')}${btn('Cancel','close','ghost wide')}`);break;
 case 'confirm-load':await loadCloud();break;
 case 'account':account();break;case 'logout':await logout();break;
 case 'relogin':exportBackup();user=null;shadow=null;blocked=false;dirty=false;clearTimeout(saveTimer);closeDialog();authScreen('Sign in again. A copy of your local progress was exported.');break;
 case 'csv':exportCSV();break;
 }}catch(e){toast(e.message||'That action could not be completed. Your previous save is retained.');}
});
document.addEventListener('pointerdown',event=>{if(event.target.id!=='map'||$('#dialog').open)return;const r=active().run;if(!r||!view||!canPlay())return;const box=event.target.getBoundingClientRect(),x=Math.floor((event.clientX-box.left-view.ox)/view.cell),y=Math.floor((event.clientY-box.top-view.oy)/view.cell);if(x===r.x&&y===r.y){contextual();return;}routeTo(x,y);});
document.addEventListener('keydown',event=>{if($('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)||event.ctrlKey||event.metaKey||event.altKey)return;if(page!=='drive'||!active().run)return;const key=event.key.toLowerCase(),dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[key]){event.preventDefault();if(performance.now()-lastKey<90)return;lastKey=performance.now();walking++;doMove(...dirs[key]);}else if(key==='e'){event.preventDefault();contextual();}else if(key==='q'){event.preventDefault();if(canPlay())afterAction(W.scan(active()));}else if(key==='r'){event.preventDefault();if(canPlay())afterAction(W.patch(active()));}else if(key==='t'){event.preventDefault();reference();}});
$('#dialog').addEventListener('cancel',event=>{if(recoveryCode){event.preventDefault();toast('Save your recovery code first.');}});
window.addEventListener('resize',drawMap);
window.addEventListener('online',()=>{if(user&&!blocked)flush();});
window.addEventListener('beforeunload',event=>{backup();if(dirty){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){walking++;backup();flush();}});
window.addEventListener('storage',event=>{if(event.key!==localKey()||!user)return;try{const other=JSON.parse(event.newValue||'null');if(other?.userId===user.id&&other.revision>revision){blocked=true;saveError='Another tab saved newer progress. Load the cloud save before continuing here.';clearTimeout(saveTimer);walking++;status();}}catch{}});
// A save is never labelled cloud-saved until the server confirms its revision.
(async()=>{try{const d=await api('session');enterAccount(d);maybeTutorial();}catch(e){authMode='login';authScreen(e.status===401?'':e.message);}})();
